  it('logs a ws error with userId and error message and answers SERVER_ERROR when listFor rejects', async () => {
    const errors: Array<{category: string; message: string; fields?: Record<string, unknown>}> = [];
    const ignore = () => undefined;
    setLogger({
      debug: ignore,
      info: ignore,
      warn: ignore,
      error: (category, message, fields) => void errors.push({category, message, fields}),
    });
    try {
      const store = {
        listFor: () => Promise.reject(new Error('database offline')),
      } as unknown as SessionStore;
      const frames: OutgoingMessage[] = [];
      const socket = {
        send: (raw: string) => void frames.push(JSON.parse(raw) as OutgoingMessage),
      } as unknown as WebSocket;
      const session: ChatSession = {sessionId: 's1', userId: 'u1', entries: []};

      await createMessageHandler({} as ChatOrchestrator, store)(socket, session, {type: 'list_sessions'});

      expect({
        frames,
        leaked: JSON.stringify(frames).includes('database offline'),
        errors,
      }).toEqual({
        frames: [{type: 'error', code: 'SERVER_ERROR', message: expect.any(String)}],
        leaked: false,
        errors: [
          {
            category: 'ws',
            message: expect.any(String),
            fields: {userId: 'u1', error: 'database offline'},
          },
        ],
      });
    } finally {
      setLogger();
    }
  });
});

